-- =============================================================================
-- PostgreSQL catalog edge cases (Phase 1.4 fixture)
-- =============================================================================
-- Fixture for the PgCatalogReader IT. The expected dump next to this file
-- (catalog-edge-cases-expected-catalog.txt) is hand-written from this DDL and
-- docs/catalog-dump-format.md; it is never generated by a reader.
--
-- Requires PostgreSQL 15+ (tested on 15 and 18). Run as one script by the
-- database owner; it drops and recreates every schema it uses.
--
-- REQUESTED SCHEMA LIST (what the IT passes to the reader):
--     "Odd Names", core, shop_east, shop_west
--
-- NOT REQUESTED (exists only as an out-of-scope target):
--     external_ref  - table currencies (FK target) and enum priority_level
--                     (referenced cross-schema; never dumped as an enum)
--
-- CASE -> OBJECT
--   composite FK, column order differs from the referenced key's declaration
--       core.stock_items.stock_items_warehouse_fk (wh_no, wh_region)
--           -> core.warehouses (warehouse_no, region_code); PK is (region_code, warehouse_no)
--   auto-named FKs in sibling schemas with same-named tables (C1)
--       shop_east.orders.orders_uid_fkey and shop_west.orders.orders_uid_fkey,
--       with different targets, nullability and actions
--   FK from a partitioned table
--       core.events.events_customer_id_fkey -> core.customers
--   FK to a partitioned table (no referenced column list -> its PK)
--       core.event_annotations.event_annotations_event_id_occurred_at_fkey
--   partitions excluded (incl. a sub-partitioned partition)
--       core.events_2025, core.events_2026 (itself partitioned), core.events_2026_h0,
--       core.events_2026_h1, core.events_default; their cloned FK rows
--       (conparentid <> 0) on core.event_annotations and on the partitions
--   unique index on a partitioned table (valid, included) / ON ONLY (invalid, excluded)
--       core.events_external_ref_uidx / core.events_only_parent_uidx
--   FK to a unique non-PK column (unique constraint)
--       shop_east.orders.orders_customer_email_fkey -> core.customers (email)
--   FK to a column covered only by a standalone unique index
--       shop_east.orders.orders_customer_tax_ref_fkey -> core.customers (tax_ref)
--   unique constraint with INCLUDE (key columns only)
--       core.stock_items.stock_items_barcode_key
--   unique index with INCLUDE (key columns only)
--       core.customers_loyalty_code_uidx
--   partial unique index (excluded)          core.customers_vip_tax_ref_uidx
--   expression unique indexes (excluded)     core.customers_email_lower_uidx,
--                                            core.customers_id_lower_email_uidx
--   non-unique index (excluded)              core.customers_created_at_idx
--   unique index duplicating a unique constraint (both listed, name tie-break)
--       core.customers_email_dup_uidx and core.customers_email_key
--   composite unique                         core.stock_items.stock_items_location_key
--   table without a PK                       "Odd Names"."no-pk$log", core.supplier_contacts
--   NOT VALID FK (included)                  core.stock_items.stock_items_reserved_for_fk
--   deferrable unique (included)             core.stock_items.stock_items_sku_key
--   identifiers: spaces, ", -, $, mixed case, embedded newline
--       schema "Odd Names"; tables "Mixed Case", "no-pk$log", "quote""d";
--       columns "a b", "a""b", "a$b", "a-b", "aB", "Line<LF>Two", "Ref<LF>No";
--       constraints "quote""d pk", "fk-to-mixed$case", "log ref fk"; enum core."Mood"
--       with labels containing ", \, a space, and the empty label
--   unique-key and FK sort order (UTF-16: space < " < $ < - < digit < upper < _ < lower)
--       "Odd Names"."Mixed Case" uniques; "Odd Names"."no-pk$log" FKs (same local
--       column, different target table, action and name)
--   int4[], varchar(20)[], numeric(10,2), int4[][], "char"
--       "Odd Names"."Mixed Case"
--   cross-schema enum (requested schema)     shop_east.orders.status -> core.order_status
--   cross-schema enum (unrequested schema)   shop_west.orders.priority -> external_ref.priority_level
--   enum arrays                              shop_east.orders.status_history,
--                                            shop_west.orders.priority_history
--   domain over an enum (and its array)      shop_east.orders.fulfilment(_history) -> core.active_status
--   domain over a built-in type              core.customers.email -> core.email_address
--   composite and range user types           core.customers.home_address, core.stock_items.price_band
--   enum label order by enumsortorder        core.order_status ('on_hold' added BEFORE 'paid')
--   dropped column (later columns keep order) core.customers.legacy_fax
--   legacy INHERITS child                    core.supplier_contacts INHERITS core.contacts;
--                                            core.contacts.phone added afterwards
--   FK to a schema outside the requested set shop_west.orders.orders_currency_fkey
--                                            -> external_ref.currencies
--   all five referential actions in both on_delete and on_update
--       see the FK comments below
--   excluded relations                       view core.customer_overview, materialized
--                                            view core.event_counts (with a unique index),
--                                            sequence core.invoice_number_seq, identity sequences
-- =============================================================================

BEGIN;

DROP SCHEMA IF EXISTS "Odd Names" CASCADE;
DROP SCHEMA IF EXISTS shop_west CASCADE;
DROP SCHEMA IF EXISTS shop_east CASCADE;
DROP SCHEMA IF EXISTS core CASCADE;
DROP SCHEMA IF EXISTS external_ref CASCADE;

-- -----------------------------------------------------------------------------
-- external_ref: NOT requested. FK target and cross-schema enum only.
-- -----------------------------------------------------------------------------
CREATE SCHEMA external_ref;

CREATE TYPE external_ref.priority_level AS ENUM ('low', 'medium', 'high');

CREATE TABLE external_ref.currencies (
    code char(3) PRIMARY KEY,
    name text NOT NULL
);

-- -----------------------------------------------------------------------------
-- core
-- -----------------------------------------------------------------------------
CREATE SCHEMA core;

-- Label order must come from enumsortorder, not from pg_enum OIDs:
-- the dump order is pending, on_hold, paid, shipped, cancelled.
CREATE TYPE core.order_status AS ENUM ('pending', 'paid', 'shipped', 'cancelled');
ALTER TYPE core.order_status ADD VALUE 'on_hold' BEFORE 'paid';

-- Mixed-case enum name; labels that need escaping in the dump, plus the empty label.
CREATE TYPE core."Mood" AS ENUM ('happy', 'so-so', 'say "hi"', 'back\slash', 'Two Words', '');

-- Domain over an enum: user_type names the domain, not core.order_status.
CREATE DOMAIN core.active_status AS core.order_status CHECK (VALUE <> 'cancelled');
-- Domain over a built-in type.
CREATE DOMAIN core.email_address AS varchar(255) CHECK (VALUE LIKE '%@%');
-- Composite and range user types (the range also creates core.price_band_multirange).
CREATE TYPE core.postal_address AS (street text, city text, postcode varchar(10));
CREATE TYPE core.price_band AS RANGE (subtype = numeric);

CREATE TABLE core.customers (
    id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email core.email_address NOT NULL,
    legacy_fax varchar(30),
    tax_ref text,
    loyalty_code text,
    is_vip boolean NOT NULL DEFAULT false,
    mood core."Mood",
    home_address core.postal_address,
    CONSTRAINT customers_email_key UNIQUE (email)
);

-- Dropped column in the middle; the column added afterwards goes last.
ALTER TABLE core.customers DROP COLUMN legacy_fax;
ALTER TABLE core.customers ADD COLUMN created_at timestamptz NOT NULL DEFAULT now();

-- Standalone unique index: the only thing making tax_ref an FK target (included).
CREATE UNIQUE INDEX customers_tax_ref_uidx ON core.customers (tax_ref);
-- Unique index with INCLUDE: only loyalty_code is dumped (included).
CREATE UNIQUE INDEX customers_loyalty_code_uidx ON core.customers (loyalty_code) INCLUDE (is_vip, created_at);
-- Same columns as customers_email_key; listed separately, ordered by name (included).
CREATE UNIQUE INDEX customers_email_dup_uidx ON core.customers (email);
-- Expression-only and mixed column/expression unique indexes (excluded).
CREATE UNIQUE INDEX customers_email_lower_uidx ON core.customers (lower(email));
CREATE UNIQUE INDEX customers_id_lower_email_uidx ON core.customers (id, lower(email));
-- Partial unique index (excluded).
CREATE UNIQUE INDEX customers_vip_tax_ref_uidx ON core.customers (tax_ref) WHERE is_vip;
-- Non-unique index (excluded).
CREATE INDEX customers_created_at_idx ON core.customers (created_at);

CREATE TABLE core.warehouses (
    region_code char(2) NOT NULL,
    warehouse_no smallint NOT NULL,
    name text NOT NULL,
    capacity numeric(10,2),
    CONSTRAINT warehouses_pkey PRIMARY KEY (region_code, warehouse_no)
);

CREATE TABLE core.stock_items (
    stock_item_id bigint GENERATED BY DEFAULT AS IDENTITY,
    wh_no smallint NOT NULL DEFAULT 0,
    wh_region char(2) NOT NULL DEFAULT 'XX',
    bin varchar(20) NOT NULL,
    sku varchar(40) NOT NULL,
    barcode varchar(20),
    qty integer NOT NULL DEFAULT 0,
    unit_price numeric(10,2) NOT NULL,
    line_value numeric(12,2) GENERATED ALWAYS AS (qty * unit_price) STORED,
    reserved_for integer,
    price_band core.price_band,
    CONSTRAINT stock_items_pkey PRIMARY KEY (stock_item_id),
    -- Deferrable unique constraint (included).
    CONSTRAINT stock_items_sku_key UNIQUE (sku) DEFERRABLE INITIALLY DEFERRED,
    -- Unique constraint with INCLUDE: only barcode is dumped.
    CONSTRAINT stock_items_barcode_key UNIQUE (barcode) INCLUDE (sku, bin),
    -- Composite unique.
    CONSTRAINT stock_items_location_key UNIQUE (wh_region, wh_no, bin),
    -- Composite FK listing columns in the opposite order to warehouses_pkey.
    -- on_delete=set_default, on_update=cascade
    CONSTRAINT stock_items_warehouse_fk FOREIGN KEY (wh_no, wh_region)
        REFERENCES core.warehouses (warehouse_no, region_code)
        ON DELETE SET DEFAULT ON UPDATE CASCADE
);

-- NOT VALID FK (included). on_delete=set_null, on_update=no_action
ALTER TABLE core.stock_items
    ADD CONSTRAINT stock_items_reserved_for_fk FOREIGN KEY (reserved_for)
    REFERENCES core.customers (id) ON DELETE SET NULL NOT VALID;

-- Partitioned table: only the parent is a table in the dump.
CREATE TABLE core.events (
    event_id bigint NOT NULL,
    occurred_at timestamptz NOT NULL,
    customer_id integer,
    external_ref uuid,
    payload jsonb,
    CONSTRAINT events_pkey PRIMARY KEY (event_id, occurred_at),
    -- FK from a partitioned table; each partition gets a cloned child row.
    -- on_delete=restrict, on_update=no_action
    CONSTRAINT events_customer_id_fkey FOREIGN KEY (customer_id)
        REFERENCES core.customers (id) ON DELETE RESTRICT
) PARTITION BY RANGE (occurred_at);

CREATE TABLE core.events_2025 PARTITION OF core.events
    FOR VALUES FROM ('2025-01-01 00:00:00+00') TO ('2026-01-01 00:00:00+00');
-- A partition that is itself partitioned (relkind 'p' and relispartition).
CREATE TABLE core.events_2026 PARTITION OF core.events
    FOR VALUES FROM ('2026-01-01 00:00:00+00') TO ('2027-01-01 00:00:00+00')
    PARTITION BY HASH (occurred_at);
CREATE TABLE core.events_2026_h0 PARTITION OF core.events_2026 FOR VALUES WITH (MODULUS 2, REMAINDER 0);
CREATE TABLE core.events_2026_h1 PARTITION OF core.events_2026 FOR VALUES WITH (MODULUS 2, REMAINDER 1);
CREATE TABLE core.events_default PARTITION OF core.events DEFAULT;

-- Unique index on the partitioned parent, cascaded to all partitions: valid (included).
CREATE UNIQUE INDEX events_external_ref_uidx ON core.events (external_ref, occurred_at);
-- ON ONLY: no partition indexes are attached, so indisvalid = false (excluded).
CREATE UNIQUE INDEX events_only_parent_uidx ON ONLY core.events (customer_id, event_id, occurred_at);

-- FK to a partitioned table with no referenced column list (resolves to events_pkey).
-- PG adds one cloned pg_constraint row per partition here, all with conparentid <> 0.
-- on_delete=cascade, on_update=no_action
CREATE TABLE core.event_annotations (
    annotation_id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    event_id bigint NOT NULL,
    occurred_at timestamptz NOT NULL,
    note text NOT NULL,
    FOREIGN KEY (event_id, occurred_at) REFERENCES core.events ON DELETE CASCADE
);

-- Legacy inheritance: the child is an ordinary table. It inherits the parent's
-- columns (first) and their NOT NULLs, but not its PK, unique or FK.
CREATE TABLE core.contacts (
    contact_id integer NOT NULL PRIMARY KEY,
    full_name text NOT NULL,
    email core.email_address UNIQUE,
    -- on_delete=no_action, on_update=restrict
    customer_id integer REFERENCES core.customers (id) ON UPDATE RESTRICT
);

CREATE TABLE core.supplier_contacts (
    supplier_code varchar(12) NOT NULL,
    CONSTRAINT supplier_contacts_supplier_code_key UNIQUE (supplier_code)
) INHERITS (core.contacts);

-- Added to the parent after the child exists: appended to the child after supplier_code.
ALTER TABLE core.contacts ADD COLUMN phone text;

-- Excluded relations.
CREATE VIEW core.customer_overview AS
    SELECT id, email, is_vip FROM core.customers;

CREATE MATERIALIZED VIEW core.event_counts AS
    SELECT customer_id, count(*) AS event_total FROM core.events GROUP BY customer_id;
CREATE UNIQUE INDEX event_counts_customer_uidx ON core.event_counts (customer_id);

CREATE SEQUENCE core.invoice_number_seq;

-- -----------------------------------------------------------------------------
-- shop_east and shop_west: sibling schemas with same-named tables and the same
-- auto-generated constraint names (users_pkey, orders_pkey, orders_uid_fkey).
-- -----------------------------------------------------------------------------
CREATE SCHEMA shop_east;

CREATE TABLE shop_east.users (
    uid integer PRIMARY KEY,
    handle text NOT NULL UNIQUE
);

CREATE TABLE shop_east.orders (
    order_id bigint PRIMARY KEY,
    -- on_delete=cascade, on_update=no_action
    uid integer NOT NULL REFERENCES shop_east.users ON DELETE CASCADE,
    -- FK to a unique non-PK column. on_delete=set_default, on_update=restrict
    customer_email core.email_address DEFAULT 'guest@example.com'
        REFERENCES core.customers (email) ON DELETE SET DEFAULT ON UPDATE RESTRICT,
    -- FK to a column covered only by a unique index. on_delete=no_action, on_update=set_default
    customer_tax_ref text REFERENCES core.customers (tax_ref) ON UPDATE SET DEFAULT,
    status core.order_status NOT NULL DEFAULT 'pending',
    status_history core.order_status[] NOT NULL DEFAULT '{}',
    fulfilment core.active_status,
    fulfilment_history core.active_status[],
    ordered_at timestamp(3) NOT NULL
);

CREATE SCHEMA shop_west;

CREATE TABLE shop_west.users (
    uid integer PRIMARY KEY,
    handle text NOT NULL
);

CREATE TABLE shop_west.orders (
    order_id bigint PRIMARY KEY,
    -- on_delete=set_null, on_update=cascade
    uid integer REFERENCES shop_west.users ON DELETE SET NULL ON UPDATE CASCADE,
    -- FK out of the requested set. on_delete=restrict, on_update=cascade
    currency char(3) NOT NULL REFERENCES external_ref.currencies (code)
        ON DELETE RESTRICT ON UPDATE CASCADE,
    -- Enum (and enum array) from the unrequested schema.
    priority external_ref.priority_level,
    priority_history external_ref.priority_level[],
    placed_on date NOT NULL
);

-- -----------------------------------------------------------------------------
-- "Odd Names": identifiers that must be quoted and escaped, and sort-order traps.
-- -----------------------------------------------------------------------------
CREATE SCHEMA "Odd Names";

-- Single-column uniques, declared in scrambled order, whose dump order is
-- "a b", "a""b", "a$b", "a-b", a1, "aB", a_b, ab. All constraint names are auto-generated.
CREATE TABLE "Odd Names"."Mixed Case" (
    "Id" integer NOT NULL,
    "ab" text UNIQUE,
    "a_b" text UNIQUE,
    "aB" text UNIQUE,
    "a1" text UNIQUE,
    "a-b" text UNIQUE,
    "a$b" text UNIQUE,
    "a""b" text UNIQUE,
    "a b" text UNIQUE,
    "Int Array" int4[],
    "Codes" varchar(20)[],
    "Matrix" int4[][],
    "Price (USD)" numeric(10,2) NOT NULL,
    "Flag" "char",
    PRIMARY KEY ("Id")
);

-- Column and constraint names with an embedded newline, a quote, a dash and a dollar.
CREATE TABLE "Odd Names"."quote""d" (
    "Line
Two" integer NOT NULL,
    "a b" text,
    CONSTRAINT "quote""d pk" PRIMARY KEY ("Line
Two"),
    -- on_delete=no_action, on_update=set_null
    CONSTRAINT "fk-to-mixed$case" FOREIGN KEY ("a b")
        REFERENCES "Odd Names"."Mixed Case" ("a b") ON UPDATE SET NULL
);

-- No PK. Several FKs on the same local column: the dump orders them by referenced
-- table, then action (NO_ACTION before CASCADE, by enum order), then name; the
-- "Ref<LF>No" FK sorts first because 'R' < 'c'.
CREATE TABLE "Odd Names"."no-pk$log" (
    logged_at timestamptz NOT NULL DEFAULT now(),
    cust integer,
    "Ref
No" integer,
    message text,
    FOREIGN KEY (cust) REFERENCES core.customers (id),
    CONSTRAINT log_cust_dup_fk FOREIGN KEY (cust) REFERENCES core.customers (id) ON DELETE CASCADE,
    CONSTRAINT log_cust_cascade_fk FOREIGN KEY (cust) REFERENCES core.customers (id) ON DELETE CASCADE,
    CONSTRAINT log_cust_contact_fk FOREIGN KEY (cust) REFERENCES core.contacts (contact_id),
    CONSTRAINT "log ref fk" FOREIGN KEY ("Ref
No") REFERENCES "Odd Names"."quote""d" ("Line
Two")
);

COMMIT;
